using UnityEngine; using UnityEditor; public class CheckRoomBounds { [MenuItem("AnhThoDien/Check Room Bounds")] public static void Check() { GameObject room = GameObject.Find("Bedroom_Shell"); if (room != null) { Renderer[] renderers = room.GetComponentsInChildren<Renderer>(); if (renderers.Length > 0) { Bounds b = renderers[0].bounds; foreach(Renderer r in renderers) b.Encapsulate(r.bounds); Debug.Log("Room Bounds: Center=" + b.center + ", Size=" + b.size + ", Min=" + b.min + ", Max=" + b.max); } } } }
